      SUBROUTINE CODEITCC---- DETERMINE INTERNALLY STORED MISALIGNMENT CODE FROM MNEMONICSC-----------------------------------------------------------------------C      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'LBDAT.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INTEGER         CODE, CODE1, CODE2, CODE3      INTEGER         REF, REF1, REF2, REF3      LOGICAL         NEWC, NEWRCC     DETERMINE PREVIOUS ALIGNMENT CODEC      NEWC = .FALSE.      NEWR = .FALSE.      IF (INDS .EQ. 0) THEN        IF (IPTYP(7) .EQ. 0) THEN          CODE = 0        ELSE          CODE = IFIX(PDATA(7))        ENDIF      ELSE         IF (IPTYP(7) .EQ. 0) THEN          DO 10 NUM = 1, NEL          IF (LABEL(NUM) .EQ. LBDAT) THEN            I = ISTOR(NUM)            GO TO 20          ENDIF   10     CONTINUE   20     CODE = IFIX(DATA(I+7))        ELSE          CODE = IFIX(PDATA(7))        ENDIF      ENDIF      CODE1 = CODE/100      CODE2 = MOD(CODE/10,10)      CODE3 = MOD(CODE,10)      IF (INDS .EQ. 0) THEN        REF = 0      ELSE IF (IPTYP(8) .EQ. 1) THEN        REF = IFIX(PDATA(8))      ELSE        REF = IFIX(DATA(I+8))      ENDIF      REF1 = REF/100      REF2 = MOD(REF/10,10)      REF3 = MOD(REF,10)CC     DETERMINE NEW ALIGNMENT CODE FROM KEYWORDSC      IF (IPTYP(10) .EQ. -2) THEN        CODE1 = 0        IPTYP(10) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(11) .EQ. -2) THEN        CODE1 = 1        IPTYP(11) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(12) .EQ. -2) THEN        CODE1 = 2        IPTYP(12) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(13) .EQ. -2) THEN        CODE2 = 0        IPTYP(13) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(14) .EQ. -2) THEN        CODE2 = 1        IPTYP(14) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(15) .EQ. -2) THEN        CODE3 = 0        IPTYP(15) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(16) .EQ. -2) THEN        CODE3 = 1        IPTYP(16) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(17) .EQ. -2) THEN        CODE3 = 2        IPTYP(17) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(18) .EQ. -2) THEN        CODE3 = 3        IPTYP(18) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(19) .EQ. -2) THEN        CODE3 = 4        IPTYP(19) = 0        NEWC = .TRUE.      ENDIF      IF (IPTYP(20) .EQ. -2) THEN        CODE3 = 5        IPTYP(20) = 0        NEWC = .TRUE.      ENDIF      CODE = 100*CODE1 + 10*CODE2 + CODE3      IF (NEWC) THEN        IPTYP(7) = 1        PDATA(7) = FLOAT(CODE)      ENDIFCC     DETERMINE NEW ALIGNMENT REFERENCE CODE FROM KEYWORDSC      IF (IPTYP(21) .EQ. -2) THEN        REF1 = 0        IPTYP(21) = 0        NEWR = .TRUE.      ENDIF      IF (IPTYP(22) .EQ. -2) THEN        REF1 = 1        IPTYP(22) = 0        NEWR = .TRUE.      ENDIF      IF (IPTYP(23) .EQ. -2) THEN        REF1 = 2        IPTYP(23) = 0        NEWR = .TRUE.      ENDIF      IF (IPTYP(24) .EQ. -2) THEN        REF2 = 0        IPTYP(24) = 0        NEWR = .TRUE.      ENDIF      IF (IPTYP(25) .EQ. -2) THEN        REF2 = 1        IPTYP(25) = 0        NEWR = .TRUE.      ENDIF      IF (IPTYP(26) .EQ. -2) THEN        REF3 = 0        IPTYP(26) = 0        NEWR = .TRUE.      ENDIF      IF (IPTYP(27) .EQ. -2) THEN        REF3 = 1        IPTYP(27) = 0        NEWR = .TRUE.      ENDIF      REF = 100*REF1 + 10*REF2 + REF3C       IF (NEWR) THEN        IPTYP(8) = 1        PDATA(8) = FLOAT(REF)      ENDIF      NWORD = 9C      RETURN      END